  "Salonun karanlık köşesinde tanımadığın bir adam yanına yaklaştı": "Un hombre que no conoces se te acercó en un rincón oscuro del gimnasio",
  "Yeni tanıştığın bir “performans koçu” seni kenara çekti": "Un “coach de rendimiento” al que acabas de conocer te llevó aparte",
  "Takım arkadaşının kuzeni olduğunu söyleyen biri mesaj attı": "Alguien que dice ser primo de tu compañero de equipo te escribió",
  "Kampta bir sağlık danışmanı fısıldayarak konuştu": "Un asesor de salud del campamento te habló en susurros",
  "💉 Karanlık Bir Teklif": "💉 Una oferta turbia",
  "{0}: “Bu kür seni {1} dövüş boyunca canavara çevirir. Testlerde çıkmaz… genelde.” Fiyatı {2}.\n\nKabul edersen vuruş, kondisyon, hız ve çene ciddi artar. Yakalanırsan 6 ay ile 2 yıl arası men, popülerlik kaybı ve sponsor iptali.": "{0}: “Este ciclo te convertirá en un monstruo durante {1} peleas. No aparecerá en los controles… normalmente.” El precio es {2}.\n\nSi aceptas, tu golpeo, cardio, velocidad y mentón suben mucho. Si te pillan: suspensión de 6 meses a 2 años, pérdida de popularidad y patrocinadores cancelados.",
  "Kabul et": "Aceptar",
  "Federasyona ihbar et": "Denunciar a la comisión",
  "Kürü aldın. Aynada başka biri var. Sonraki {0} dövüşte çok güçlüsün… ama her dövüşten sonra test riski var.": "Tomaste el ciclo. Hay otra persona en el espejo. Serás muy fuerte en las próximas {0} peleas… pero cada pelea conlleva riesgo de control.",
  "Kibarca reddettin. Temiz bir kariyer, huzurlu bir uyku.": "Lo rechazaste con cortesía. Una carrera limpia, un sueño tranquilo.",
  "Federasyona ihbar ettin. Basın seni “temiz sporun sesi” ilan etti. Popülerlik +2.": "Lo denunciaste a la comisión. La prensa te llamó “la voz del deporte limpio”. Popularidad +2.",
  "💼 Sponsorluk Teklifi": "💼 Oferta de patrocinio",
  "Bahis": "Apuestas",
  "\n\nAma bir bahis şirketi… Bazı taraftarların hoşuna gitmeyebilir.": "\n\nPero es una casa de apuestas… A algunos fans puede no gustarles.",
  "{0} seninle çalışmak istiyor. Şortunda logoları olacak, karşılığında {1} ödeyecekler.{2}": "{0} quiere trabajar contigo. Sus logos irán en tu pantalón y te pagarán {1}.{2}",
  "Pazarlık yap (+%50 dene)": "Negociar (intentar +50%)",
  " (Bazı taraftarlar tepkili: popülerlik -2)": " (Algunos fans están molestos: popularidad -2)",
  "{0} ile anlaştın. +{1}{2}": "Firmaste con {0}. +{1}{2}",
  "Sıkı pazarlık işe yaradı! +{0}": "¡La negociación dura dio frutos! +{0}",
  "{0} masadan kalktı. \"Başka dövüşçüler de var.\"": "{0} se retiró. \"Hay otros peleadores.\"",
  "Teklifi reddettin. İmajın temiz kaldı.": "Rechazaste la oferta. Tu imagen sigue limpia.",
  "Antrenmanda sparring partnerini uyuttuğun bir video 2 milyon izlendi. Yorumlar ikiye bölünmüş durumda. Ne paylaşırsın?": "Un video tuyo noqueando a tu compañero de sparring llegó a 2 millones de vistas. Los comentarios están divididos. ¿Qué publicas?",
  "Sıklettekilere laf at": "Desafía a la categoría",
  "Mütevazı bir teşekkür yaz": "Escribe un agradecimiento humilde",
  "Görmezden gel": "Ignóralo",
  "Paylaşımın ortalığı yıktı. Rakipler cevap yazıyor, gazeteciler seni arıyor. Popülerlik +5.": "Tu publicación explotó. Los rivales responden, los periodistas llaman. Popularidad +5.",
  "Kibirli buldular. \"Önce bir kemer kazan\" yorumları ağır bastı. Popülerlik -3.": "Les pareció arrogante. Los comentarios de \"primero gana un cinturón\" coparon todo. Popularidad -3.",
  "Samimi mesajın sevildi. Popülerlik +2.": "Tu mensaje sincero encantó. Popularidad +2.",
  "Hiçbir şey yazmadın. Video kendi kendine yayılmaya devam etti. Popülerlik +1.": "No publicaste nada. El video siguió difundiéndose solo. Popularidad +1.",
  "🏟️ Salon Değiştirme Fırsatı": "🏟️ Una oportunidad de cambiar de gimnasio",
  "{0} baş antrenörü {1} seni takımında görmek istiyor (kalite {2}/10). Davetli olduğun için geçiş ücreti yarı fiyat: {3}.\n\nŞu anki hocan {4} (kalite {5}/10) seni sıfırdan yetiştirdi.": "El entrenador jefe de {0}, {1}, te quiere en su equipo (calidad {2}/10). Como estás invitado, el traspaso cuesta la mitad: {3}.\n\nTu entrenador actual, {4} (calidad {5}/10), te formó desde cero.",
  "Taşın": "Cambiarte",
  "Kal, sadakat önemli": "Quedarte, la lealtad importa",
  "Paran yetmiyor ({0} gerekli). Fırsat kaçtı.": "No te alcanza (se necesitan {0}). La oportunidad se esfumó.",
  "Yeni evin: {0}. {1} telefonda sessizce \"Başarılar evlat\" dedi ve kapattı.": "Tu nuevo hogar: {0}. Al teléfono, {1} dijo en voz baja \"Suerte, chico\" y colgó.",
  "Kaldın. Hocan gözleri dolarak sarıldı. Sonraki kampta ekstra motivasyonla çalışacaksın.": "Te quedaste. Tu entrenador te abrazó con lágrimas en los ojos. Entrenarás con motivación extra el próximo campamento.",
  "🤝 Menajer Teklifi": "🤝 Oferta de representación",
