  "Şu an yapamam": "Ahora no puedo",
  "Parayı gönderdin. Ameliyat başarılı geçti. Babanın mesajı: \"Oğlumla gurur duyuyorum.\" Motivasyonun tavan.": "Enviaste el dinero. La operación salió bien. El mensaje de tu padre: \"Estoy orgulloso de ti.\" Tu motivación está por las nubes.",
  "Yarısını gönderdin, gerisini akrabalar tamamladı. İçin rahat.": "Enviaste la mitad, los familiares cubrieron el resto. Tienes la conciencia tranquila.",
