  "Elleri kontrol ettin, açıyı kırdın ve {0} kilidinden çıktın!": "¡Controlaste las manos, rompiste el ángulo y escapaste del {0}!",
  "Patlayıcı bir köprüyle sıyrıldın ve üste geçtin! Seyirci çıldırıyor!": "¡Escapaste con un puente explosivo y quedaste arriba! ¡El público enloquece!",
  "🦴 Tap atmayı reddettin… bir çıtırtı. Hakem durdurdu. {0} {1} ile kazandı.": "🦴 Te negaste a rendirte… un crujido. El árbitro lo detuvo. {0} ganó por {1}.",
