  "{ph} ile aynı kafese girmek için sabırsızlanıyorum. Sabırsızlığım onun korkusundan büyük. 😈": "Tengo ganas de entrar a la jaula con {ph}. Mi impaciencia es más grande que su miedo. 😈",
