  "{ph} sosyal medyada çok cesur. Bakalım kafes kapısı kapanınca da öyle mi?": "{ph} es muy valiente en redes. Veremos si le dura cuando se cierre la jaula.",
  "Herkes {p} diyor… Ben kimseyi görmüyorum. 🥱": "Todos dicen {p}… yo no veo a nadie. 🥱",
  "{ph} taraftarlarına söyleyin, mendillerini hazırlasınlar.": "Díganles a los fans de {ph} que preparen los pañuelos.",
