  "Cevabın viral oldu, rekabet kızıştı!": "¡Tu respuesta se hizo viral, la rivalidad se calentó!",
  "Cevabın biraz fazla kaçtı, eleştiri aldın.": "Tu respuesta se pasó un poco, te criticaron.",
