  "{0}, iyi bir savaş olacak. 🤝": "{0}, será una buena guerra. 🤝",
  "Olgun tavrın takdir topladı.": "Tu actitud madura recibió elogios.",
  "Salonumuza yeni bir savaşçı katıldı: {0}. {1} bu ismi yakında çok duyacak! 🥊": "Un nuevo guerrero se unió a nuestro gimnasio: {0}. ¡{1} oirá mucho este nombre pronto! 🥊",
  "KULİS: {org} yönetimi {a} ile {b} maçını ayarlamak üzere. Tarih belli değil.": "EXCLUSIVA: la directiva de {org} está a punto de armar {a} vs {b}. Aún sin fecha.",
  "KULİS: {a} kampında sakatlık yaşadığı konuşuluyor. Takımı yalanlamadı.": "EXCLUSIVA: dicen que {a} se lesionó en el campamento. El equipo no lo desmintió.",
  "KULİS: {p} için birden fazla sponsor teklif hazırlığında.": "EXCLUSIVA: varios patrocinadores preparan ofertas para {p}.",
  "KULİS: {c} bir sonraki kemer savunmasında sürpriz bir isimle karşılaşabilir.": "EXCLUSIVA: {c} podría enfrentar a un nombre sorpresa en su próxima defensa del título.",
  "KULİS: {a} sıklet değiştirmeyi düşünüyor.": "EXCLUSIVA: {a} está considerando cambiar de categoría.",
  "KULİS: {b} menajeriyle yollarını ayırdı. Kontrat müzakereleri tıkandı.": "EXCLUSIVA: {b} se separó de su mánager. Las negociaciones de contrato se estancaron.",
  "KULİS: {org} gelecek ay büyük bir organizasyon için {p} adını listeye yazdı.": "EXCLUSIVA: {org} puso el nombre de {p} en la lista para un gran evento el mes que viene.",
  "KULİS: {a} ve {b} arasında salon kavgası iddiası! Görgü tanıkları konuşuyor.": "EXCLUSIVA: ¡reportan una pelea en el gimnasio entre {a} y {b}! Los testigos hablan.",
  "KULİS: {c} kemeri boşaltmayı düşünüyor mu? Yakın çevresi sessiz.": "EXCLUSIVA: ¿{c} piensa dejar vacante el cinturón? Su círculo guarda silencio.",
  "KULİS: {p} ile ilgilenen bir film yapımcısı olduğu söyleniyor. 🎬": "EXCLUSIVA: al parecer un productor de cine está interesado en {p}. 🎬",
  "KULİS: {a} doping testinden geçemedi mi? Resmi açıklama bekleniyor.": "EXCLUSIVA: ¿{a} dio positivo en un control antidopaje? Se espera un comunicado oficial.",
  "KULİS: {b} emekliliği düşünüyor. Son maçını memleketinde yapmak istiyor.": "EXCLUSIVA: {b} piensa en retirarse. Quiere su última pelea en su ciudad natal.",
  "ANKET: {a} vs {p} olsa kim kazanır? 🗳️ {a} %{x} · {p} %{y}": "ENCUESTA: {a} vs {p}, ¿quién gana? 🗳️ {a} {x}% · {p} {y}%",
  "ANKET: Sıkletin en iyi vuruşçusu kim? 🗳️ {a} %{x} · {p} %{y}": "ENCUESTA: ¿Mejor golpeador de la categoría? 🗳️ {a} {x}% · {p} {y}%",
  "ANKET: {c} kemeri daha kaç maç tutar? 🗳️ 1-2 maç %{x} · 3+ maç %{y}": "ENCUESTA: ¿Cuántas peleas más retendrá {c} el cinturón? 🗳️ 1-2 peleas {x}% · 3+ peleas {y}%",
  "ANKET: Yılın nakavtı kimin? 🗳️ {p} %{y} · {b} %{x}": "ENCUESTA: ¿De quién fue el nocaut del año? 🗳️ {p} {y}% · {b} {x}%",
  "ANKET: {p} ayakta mı daha tehlikeli, yerde mi? 🗳️ Ayakta %{x} · Yerde %{y}": "ENCUESTA: ¿{p} es más peligroso de pie o en el suelo? 🗳️ De pie {x}% · Suelo {y}%",
  "ANKET: {a} trash talk’ta haklı mı? 🗳️ Evet %{x} · Hayır %{y}": "ENCUESTA: ¿Tiene razón {a} en el trash talk? 🗳️ Sí {x}% · No {y}%",
  "ANKET: Sıklette bir sonraki şampiyon kim olur? 🗳️ {p} %{y} · {b} %{x}": "ENCUESTA: ¿Quién será el próximo campeón de la categoría? 🗳️ {p} {y}% · {b} {x}%",
  "ANKET: {org} en iyi maçı hangisiydi? 🗳️ {a} vs {b} %{x} · {p} maçı %{y}": "ENCUESTA: ¿Cuál fue la mejor pelea de {org}? 🗳️ {a} vs {b} {x}% · la pelea de {p} {y}%",
  "📊 ANALİZ: {p} son maçlarında {stat} istatistiğinde ciddi gelişme gösterdi. Sıklet dikkat!": "📊 ANÁLISIS: {p} ha mostrado una mejora seria en {stat} en sus últimas peleas. ¡Categoría, tomen nota!",
