  "{hoca}: “Bu salondan bir şampiyon çıkacak. Yazın bir kenara.”": "{hoca}: “De este gimnasio saldrá un campeón. Apúntenlo.”",
  "Memleketime döndüm, mahalledeki çocuklarla antrenman yaptık. ❤️": "Volví a casa y entrené con los chicos del barrio. ❤️",
