  "Amatör ligde resmi sıralama yok. Profesyonel olduğunda organizasyonunun sıklet sıralaması burada açılacak.": "En la liga amateur no hay ranking oficial. Cuando pases a profesional, aquí aparecerá el ranking de tu categoría.",
  "Bu organizasyonda sıralama yok. Tek gecelik bir fırsat: kazanırsan kapılar açılır.": "Esta promotora no tiene ranking. Una oportunidad de una noche: gana y se abren puertas.",
