  "Kalan adımları biz seçelim: branş, sıklet, görünüm ve hikâye. Hemen salona gir, her şeyi sonradan oynarken öğrenirsin.": "Nosotros elegimos el resto: disciplina, categoría, aspecto e historia. Entra directo al gimnasio y aprende jugando.",
  "Hemen başla": "Empezar ya",
  "ya da DEVAM ile karakterini adım adım kendin kur": "o pulsa CONTINUAR para crear tu peleador paso a paso",
  "🏁 Rekabet bitti! {0} sonunda kabul etti: \"Sen daha iyiydin, {1}.\" Aranızdaki seri: {2}. Popülerlik +5.": "🏁 ¡Se acabó la rivalidad! {0} por fin lo admitió: \"Fuiste mejor, {1}.\" Serie: {2}. Popularidad +5.",
  "Bugün kafeste daha iyi olan kazandı. Saygılar {0}. Bu rekabet beni daha iyi bir dövüşçü yaptı.": "Esta noche ganó el mejor. Respeto, {0}. Esta rivalidad me hizo mejor peleador.",
  "🏁 {0} emekliliğini açıkladı: \"Kariyerimdeki en zor rakip sendin, {1}.\" Seriyi sen kazandın: {2}.": "🏁 {0} anunció su retiro: \"Fuiste el rival más duro de mi carrera, {1}.\" Ganaste la serie: {2}.",
  "🏁 {0} emekliliğini açıkladı. Aranızdaki seri: {1}. Onu hiç tam geçemedin; bu hikâye böyle bitti.": "🏁 {0} anunció su retiro. Serie: {1}. Nunca llegaste a superarlo del todo; así termina esta historia.",
  "⚔️ Ezeli rakibin {0} karşısında kazandın! Aranızdaki seri: {1}.": "⚔️ ¡Venciste a tu némesis {0}! Serie: {1}.",
  "Bu gece senin gecendi. Ama bu iş bitmedi, {0}.": "Esta noche fue tuya. Pero esto no ha terminado, {0}.",
  "Rövanş istiyorum. Organizasyon duysun!": "Quiero la revancha. ¡Que lo escuche la liga!",
  "Şans bir kez güler. Üçüncü maçta görüşürüz.": "La suerte sonríe una sola vez. Nos vemos en la próxima.",
  "⚔️ Ezeli rakibinle berabere. Aranızdaki seri: {0}. Kimse tatmin olmadı.": "⚔️ Empate con tu némesis. Serie: {0}. Nadie quedó satisfecho.",
  "⚔️ {0} yine kazandı. Aranızdaki seri: {1}. Bu iş bitmedi.": "⚔️ {0} volvió a ganar. Serie: {1}. Esto no ha terminado.",
  "Söylemiştim. Kafeste ne zaman karşılaşsak aynı son. 😏": "Te lo dije. Cada vez que nos vemos en la jaula, el mismo final. 😏",
  "{0}, bir daha karşıma çıkmadan önce iki kere düşün.": "{0}, piénsalo dos veces antes de volver a enfrentarme.",
  "Kral benim. Anlaşıldı mı?": "El rey soy yo. ¿Entendido?",
  "🗡️ {0} maçtan sonra mikrofonu aldı: \"Bu daha başlangıç. Kafeste her karşılaştığımızda aynı sonuç olacak.\" Bu isim peşini kolay bırakmayacak: artık bir ezeli rakibin var.": "🗡️ {0} tomó el micrófono tras la pelea: \"Esto es solo el comienzo. Cada vez que nos veamos en la jaula, terminará igual.\" Este nombre no te soltará fácilmente: ahora tienes una némesis.",
  "{0} iyi dövüşçü ama bana göre değil. Ne zaman isterse tekrar.": "{0} es buen peleador, pero no está a mi nivel. Cuando quiera, otra vez.",
  "🗡️ {0} kameralara konuştu: \"{1} yenilmez sanılıyor. O balonu ben patlatacağım.\" Yeni bir ezeli rakibin var.": "🗡️ {0} habló ante las cámaras: \"Todos creen que {1} es invencible. Yo voy a reventar esa burbuja.\" Tienes una nueva némesis.",
  "{0}, kaçamazsın. Sıra bende.": "{0}, no puedes huir. Voy yo.",
  "{1} karşısında kazanmak mı? Onu ben de yenerdim. Asıl sınav benim, {0}.": "¿Ganarle a {1}? Yo también le ganaría. La verdadera prueba soy yo, {0}.",
  "Herkes seni konuşuyor {0}. Ben hâlâ o geceyi hatırlıyorum. 😏": "Todos hablan de ti, {0}. Yo todavía recuerdo aquella noche. 😏",
  "Güzel galibiyet {0}. Ama bir gün yine karşılaşacağız.": "Buena victoria, {0}. Pero algún día volveremos a vernos.",
  "{0} formda görünüyor. Ben de. Tarih verin.": "{0} se ve en forma. Yo también. Pongan la fecha.",
  "{1} bile seni yendi. Ben sana söylemiştim, {0}.": "Hasta {1} te ganó. Te lo dije, {0}.",
  "Kafeste yerin yok, {0}. Bunu en iyi ben biliyorum.": "No perteneces a la jaula, {0}. Nadie lo sabe mejor que yo.",
