  "Destekle, onu çalıştır": "Apóyalo, entrénalo",
  "Vazgeçirmeye çalış": "Intenta convencerlo de que no",
  "Sabah koşularına artık baban da geliyor. Salonda herkes ona “Usta” diyor. Motivasyon +1.": "Ahora tu padre sale a correr contigo por las mañanas. En el gimnasio todos lo llaman “Maestro”. Motivación +1.",
  "Ona riskleri anlattın. Sessizce dinledi, bir şey demedi.": "Le explicaste los riesgos. Escuchó en silencio y no dijo nada.",
  "💔 Kırgın Bir Baba": "💔 Un padre dolido",
  "Baban yardım gecesine çıkmadı ama sana kırgın: “Sen kendi yolunu seçtin, ben de bir kez seçmek istemiştim.”": "Tu padre no peleó en la noche benéfica, pero está dolido: “Tú elegiste tu camino. Yo quería elegir el mío, una sola vez.”",
  "Özür dile, onu bir sonraki maçına davet et": "Pídele perdón e invítalo a tu próxima pelea",
  "Zamanla geçer": "El tiempo lo arreglará",
  "🎉 Babanın Gecesi": "🎉 La noche de tu padre",
  "Baban üç raunt boyunca dimdik durdu ve salon ayağa kalktı! Onu ringte kucakladığın video her yerde.": "¡Tu padre aguantó de pie tres asaltos y todo el recinto se levantó! El video de ustedes abrazados en el ring está en todas partes.",
  "Onunla gurur duy": "Siéntete orgulloso de él",
  "🏥 Zor Bir Gece": "🏥 Una noche dura",
  "Baban ikinci rauntta düştü. İyi, ama bir gece hastanede kalacak. Masraflar {0}.": "Tu padre cayó en el segundo asalto. Está bien, pero pasará una noche en el hospital. Los gastos suman {0}.",
  "Yanında ol": "Quédate a su lado",
  "Maç gecesi baban ilk sıradaydı. Aranızdaki buz eridi. Motivasyon +1.": "La noche de la pelea tu padre estaba en primera fila. El hielo entre ustedes se derritió. Motivación +1.",
  "Aranızdaki mesafe büyüdü. Motivasyon -1.": "La distancia entre ustedes creció. Motivación -1.",
  "Baba-evlat hikâyesi herkesin yüreğine dokundu. Popülerlik +4, motivasyon +1.": "La historia de padre e hijo tocó el corazón de todos. Popularidad +4, motivación +1.",
  "Sabaha kadar yanındaydın. Taburcu olurken gülümsedi: “Değdi.” Motivasyon +1.": "Estuviste con él hasta la mañana. Al salir del hospital sonrió: “Valió la pena.” Motivación +1.",
  "YOL: Kafesten Kemere · {0} {1} kariyer kodu (Menü → Kariyer içe aktar):": "YOL: De la jaula al cinturón · código de carrera de {0} {1} (Menú → Importar carrera):",
  "Kariyer kodu kopyalandı. Yeni cihazda Menü → Kariyer içe aktar.": "Código de carrera copiado. En el nuevo dispositivo: Menú → Importar carrera.",
