  "Kod okunamadı. Tamamını kopyaladığından emin ol.": "No se pudo leer el código. Asegúrate de copiarlo completo.",
  "Boş yuva yok. Önce bir kariyeri sil ya da yuvaları artır.": "No hay ranura libre. Borra una carrera o desbloquea más ranuras.",
