  "Reddettin. Kafan rahat, odağın yerinde.": "Lo rechazaste. Mente tranquila, concentración intacta.",
  "Kabul et gibi yap": "Finge aceptar",
  "Hem bilgiyi aldın hem de elini göstermedin. Yapımcılar bayıldı.": "Conseguiste la información sin mostrar tus cartas. A los productores les encantó.",
  "İkili oyunun itiraf odasında ortaya çıktı! {0} artık en büyük düşmanın.": "¡Tu doble juego salió a la luz en el confesionario! {0} es ahora tu peor enemigo.",
  "Evde parti": "Fiesta en la casa",
  "Yapımcılar eve müzik ve pizza soktu. Ev arkadaşların dans ediyor, kameralar seni arıyor.": "Los productores metieron música y pizza en la casa. Tus compañeros bailan, las cámaras te buscan.",
  "Partinin yıldızı ol": "Sé el alma de la fiesta",
  "Sabaha kadar dans ettin. Herkes seni seviyor ama sabah antrenmanında ölüyordun.": "Bailaste hasta el amanecer. Todos te quieren, pero en el entrenamiento de la mañana te morías.",
  "Erkenden yat": "Acuéstate temprano",
  "Gürültüye rağmen uyudun. Sabah taptazesin.": "Dormiste a pesar del ruido. Por la mañana estás como nuevo.",
  "Gizlice idman yap": "Entrena en secreto",
  "Herkes eğlenirken bodrumda ip atladın. Kimse görmedi ama vücudun gördü.": "Mientras todos festejaban, saltaste a la cuerda en el sótano. Nadie lo vio, pero tu cuerpo sí.",
  "İtiraf odası": "Confesionario",
  "Kırmızı ışık yandı. Yapımcı soruyor: \"Rakibin {0} hakkında ne düşünüyorsun?\"": "Se enciende la luz roja. El productor pregunta: \"¿Qué piensas de tu rival {0}?\"",
  "Ateş püskür": "Echa fuego",
  "\"Onu kafeste uyutacağım.\" Bölüm bu sözle tanıtıldı. Ama rakibin de bunu izledi.": "\"Lo voy a dormir en la jaula.\" El episodio se promocionó con esa frase. Pero tu rival también lo vio.",
  "\"İyi dövüşçü, ama hazırım.\" Sakin ve kendinden emin.": "\"Buen peleador, pero estoy listo.\" Tranquilo y seguro.",
  "Hikâyeni anlat": "Cuenta tu historia",
  "Mahallende başlayan yolculuğunu anlattın. İzleyiciler gözyaşlarını tutamadı.": "Contaste tu viaje desde el barrio. Los espectadores no pudieron contener las lágrimas.",
  "Koç oyunu": "Desafío de entrenadores",
  "Haftanın koç oyunu: halat tırmanma, lastik devirme ve sprint. Kazanan takıma $5.000 ve bir gece serbest.": "Desafío de la semana: subir la cuerda, voltear neumáticos y sprint. El equipo ganador gana $5.000 y una noche libre.",
  "Tüm gücünle yüklen": "Dalo todo",
  "Takımı yönet, taktik ver": "Dirige al equipo",
  "Takımını dakikası dakikasına yönettin ve kazandınız! Payına $2.500.": "¡Dirigiste a tu equipo minuto a minuto y ganasteis! Tu parte: $2.500.",
  "Taktiğin tutmadı, ikinci oldunuz.": "Tu táctica no funcionó, quedasteis segundos.",
  "Sakatlanmamak için yavaş git": "Ve despacio para no lesionarte",
  "Takım arkadaşların sana surat astı ama vücudun maça sağlam.": "Tus compañeros se enfadaron, pero tu cuerpo está listo para pelear.",
  "Eve özlem": "Nostalgia",
  "Üç haftadır telefon yok. Yapımcılar ailenden gelen bir mektup getirdi.": "Tres semanas sin teléfono. Los productores trajeron una carta de tu familia.",
  "Kameraların önünde oku": "Léela ante las cámaras",
  "Sesin titredi, bütün ev sana sarıldı. Bölümün en çok izlenen anı.": "Te tembló la voz, toda la casa te abrazó. El momento más visto del episodio.",
  "Yalnızken oku": "Léela a solas",
  "Mektubu yastığının altına koydun. Kimin için dövüştüğünü hatırladın.": "Pusiste la carta bajo la almohada. Recordaste por quién peleas.",
  "Okuma, aklın dağılmasın": "No la leas, mantén la cabeza",
  "Mektubu açmadın. Ama her gece aklına geldi.": "No abriste la carta. Pero la pensaste cada noche.",
  "Salonda kavga": "Pelea en el gimnasio",
  "{0} ile başka bir ev arkadaşı antrenmanda birbirine girdi. Herkes sana bakıyor.": "{0} y otro compañero se pelearon en el entrenamiento. Todos te miran.",
  "Araya gir, ayır": "Métete y sepáralos",
  "İkisini de ayırdın. Ev sana lider gözüyle bakıyor.": "Los separaste. La casa te ve como un líder.",
  "Telefonla çek": "Grábalo",
  "Görüntü bölüm fragmanına girdi. {0} bunu unutmayacak.": "La grabación salió en el avance. {0} no lo olvidará.",
  "Gaz ver": "Échale leña",
  "\"Vur! Vur!\" Yapımcılar sevindi, ev karıştı.": "\"¡Dale! ¡Dale!\" Los productores encantados, la casa revuelta.",
  "Sızıntı": "La filtración",
  "Biri senin antrenman notlarını bulup {0} adlı ev arkadaşına vermiş. Kim yaptı?": "Alguien encontró tus notas de entrenamiento y se las dio a {0}. ¿Quién fue?",
  "Bütün evi topla, hesap sor": "Reúne a la casa y exige respuestas",
  "Toplantı kavgaya döndü, kimse suçu üstlenmedi. Bölümün finali buydu.": "La reunión acabó en pelea, nadie confesó. Ese fue el final del episodio.",
  "Planını değiştir": "Cambia tu plan",
  "Notları değiştirdin. Artık onlar yanlış bilgiyle hazırlanıyor.": "Cambiaste las notas. Ahora se preparan con información falsa.",
  "Sahte not bırak": "Deja una nota falsa",
  "Masaya \"sol kroşem zayıf\" yazan bir kâğıt bıraktın. Yem atıldı.": "Dejaste en la mesa un papel que decía \"mi gancho izquierdo es débil\". El anzuelo está puesto.",
  "Halatın tepesine ilk sen çıktın! Takımın kazandı: +$5.000, ekran süresi +8.": "¡Llegaste primero a lo alto de la cuerda! Tu equipo ganó: +$5.000, pantalla +8.",
  "Sprintte arka adalen çekti. Kaybettiniz ve sağlık -6.": "Te dio un tirón en el isquio en el sprint. Perdisteis y salud -6.",
  "Son ana kadar zorladın ama diğer takım kazandı.": "Lo diste todo hasta el final, pero ganó el otro equipo.",
  "Odak {0}{1}: zihin ve kondisyon": "Concentración {0}{1}: mente y cardio",
  "🤝 Müttefikin {0}, rakibin zayıf yanını anlattı: {1}": "🤝 Tu aliado {0} te contó el punto débil del rival: {1}",
  "😤 {0} sana kin bağladı: daha hırslı gelecek": "😤 {0} te guarda rencor: vendrá con más hambre",
  "💔 Müttefikinle karşı karşıyasın. Dostluk kafes kapısında biter.": "💔 Te enfrentas a tu aliado. La amistad termina en la puerta de la jaula.",
  "Koçun": "Tu entrenador",
  "🏆 {0} turunu geçtin!": "🏆 ¡Superaste la ronda de {0}!",
  "❌ {0} turunda elendin.": "❌ Eliminado en {0}.",
  "💵 Bölüm ücreti: ${0}": "💵 Pago del episodio: ${0}",
  "📺 Ev arkadaşlarından {0} kişi kaldı.": "📺 Quedan {0} peleadores en la casa.",
  "📲 Şov bitti. Ekran süresi {0}/100: {1} takipçi, popülerlik +{2}.": "📲 Terminó el show. Pantalla {0}/100: {1} seguidores, popularidad +{2}.",
  "🏆 KAFES EVİ ŞAMPİYONU! Kupa ve $20.000 ödül. Büyük organizasyonlar telefonda.": "🏆 ¡CAMPEÓN DE LA CASA DE LA JAULA! Trofeo y $20.000. Las grandes promotoras llaman.",
  "🏆 {0}, Kafes Evi'nin yeni sezon şampiyonu oldu!": "🏆 ¡{0} es el campeón de la nueva temporada de La Casa de la Jaula!",
  "📺 Kafes Evi maceran sona erdi ({0}).": "📺 Tu aventura en La Casa de la Jaula terminó ({0}).",
  "KAFES EVİ SEÇMELERİ": "CASTING DE LA CASA DE LA JAULA",
  "Realite şovu yeni sezon için seni istiyor: 8 dövüşçü aynı evde, her hafta eleme maçı. Maçlar karnene işlenmez. Şampiyona büyük organizasyon kontratı ve $20.000.": "El reality te quiere para la nueva temporada: 8 peleadores en una casa, una pelea eliminatoria cada semana. No cuentan en tu récord. El campeón gana un contrato con una gran promotora y $20.000.",
  "Eve gir": "Entrar en la casa",
  "KAFES EVİ · {0}": "LA CASA DE LA JAULA · {0}",
  "Kameralar 7/24 açık. Ne yaparsan ekranda.": "Cámaras 24/7. Todo lo que hagas sale en pantalla.",
  "Bölüm sonu": "Fin del episodio",
  "Bölüm {0}": "Episodio {0}",
