  "MÜTTEFİK": "ALIADO",
  "Evden çık": "Salir de la casa",
  "Sonraki bölüm": "Siguiente episodio",
  "ELEME TABLOSU": "CUADRO",
  "🏆 Kafes Evi şampiyonluğu bütün kapıları açtı. Büyük organizasyonlar seni kadrosunda istiyor!": "🏆 El título de La Casa de la Jaula abrió todas las puertas. ¡Las grandes promotoras te quieren!",
  "📺 Finale kadar gittin ve herkes seni tanıdı. Profesyonel teklifler geldi!": "📺 Llegaste a la final y todos te conocen. ¡Llegaron ofertas profesionales!",
  "Kafes Evi şampiyonuna özel kontrat.": "Contrato especial para el campeón de La Casa de la Jaula.",
  "Mevcut organizasyonun seni bırakmak istemiyor.": "Tu promotora actual no quiere dejarte ir.",
  "Kafes Evi": "La Casa de la Jaula",
  "Kritik": "Crítico",
  "Ciddi hasar": "Daño grave",
  "Belirgin hasar": "Daño notable",
