  "TAP ATTIN": "TE RENDISTE",
  "🔒 ya da ⤴️ görünce KONTROL. Rakip yorulunca SUB dene.": "¿Ves 🔒 o ⤴️? CONTROL. Busca la SUMISIÓN cuando esté cansado.",
