  "🌍 Eski rakibin {0}, şampiyon olarak eldivenlerini astı.": "🌍 Tu viejo rival {0} se retiró como campeón.",
  "🌍 Bir zamanlar yendiğin {0} emekli oldu.": "🌍 {0}, a quien venciste, se ha retirado.",
  "🌍 Yendiğin {0} toparlandı: {1} maçtır kazanıyor.": "🌍 {0}, a quien venciste, se recuperó: {1} victorias seguidas.",
  "🌍 {0} senden sonra bir türlü toparlanamadı, üst üste kaybediyor.": "🌍 {0} no se recuperó tras perder contigo y sigue perdiendo.",
  "🌍 Bir zamanlar yendiğin {0}, {1} ile sözleşme imzaladı!": "🌍 {0}, a quien venciste, firmó con {1}!",
