  "Bir yapımcı seni “{0}” adlı aksiyon filminde kötü adam olarak istiyor. Çekimler üç hafta, Hollywood'dan bir yönetmen.": "Un productor te quiere como villano en la película de acción “{0}”. Tres semanas de rodaje, director de Hollywood.",
  "Sette herkes senden korktu, sonra sevdi. Fragman bir günde 20 milyon izlendi.": "En el set todos te temieron y luego te adoraron. El tráiler tuvo 20 millones de visitas en un día.",
  "🎥 Belgesel Teklifi": "🎥 Oferta de Documental",
  "Bir yayın platformu senin hayatını anlatan bir belgesel çekmek istiyor. Kamera ekibi bir sonraki kampın boyunca peşinde olacak; memleketine, ailene de gidecekler.": "Una plataforma quiere rodar un documental sobre tu vida. Un equipo te seguirá en el próximo campamento y visitará tu ciudad y tu familia.",
  "Kafesten Kemere": "De la Jaula al Cinturón",
  "Kamera her şeyi çekti: sabah koşularını, kesimin zor anlarını, annenin mutfağını. İzleyiciler seni tanıdı.": "La cámara lo grabó todo: las carreras matinales, lo duro del corte de peso, la cocina de tu madre. El público te conoció.",
  "📺 Reklam Yüzü": "📺 Imagen de Campaña",
  "{0} yeni kampanyasının yüzü olmanı istiyor. Bir günlük çekim, ülke çapında billboard.": "{0} quiere que seas la imagen de su nueva campaña. Un día de rodaje, vallas por todo el país.",
  "Şehrin her köşesinde yüzün var. Annen her billboard'un fotoğrafını çekiyor.": "Tu cara está en cada esquina de la ciudad. Tu madre fotografía cada valla.",
  "🎙️ Talk Show Daveti": "🎙️ Invitación a un Programa",
  "“{0}” programı seni konuk olarak çağırdı. Sunucu ünlü, şaka kaldırırsa salon seninle.": "“{0}” te invitó como invitado. El presentador es famoso; si aguantas bromas, el público es tuyo.",
  "Sunucuya canlı yayında armbar gösterdin. Klip her yerde.": "Le hiciste una palanca de brazo al presentador en directo. El clip está en todas partes.",
  "📰 Dergi Kapağı": "📰 Portada de Revista",
  "{0} dergisi seni kapağa koymak istiyor. Bir günlük çekim, büyük bir röportaj.": "La revista {0} te quiere en portada. Un día de fotos y una gran entrevista.",
  "Kapak büfelerde tükendi. Bir kopyası salonun duvarında.": "La revista se agotó en los quioscos. Una copia cuelga en el gimnasio.",
  "📺 Dizi Konuk Rolü": "📺 Cameo en una Serie",
  "Sevilen dizi “{0}” bir bölümde seni kendini oynaman için istiyor. İki hafta çekim.": "La exitosa serie “{0}” quiere que te interpretes a ti mismo en un episodio. Dos semanas de rodaje.",
  "Sahnen sosyal medyada dolaştı. Senaristler “bir sezon daha gel” diyor.": "Tu escena circuló por las redes. Los guionistas quieren que vuelvas la próxima temporada.",
