  "Söylentilere kulak asmadın, kendi işine baktın.": "Ignoraste los rumores y te centraste en lo tuyo.",
  "🕵️ Söylenti doğruydu: {0} sakat çıktı ve sen tam oraya hazırlandın (IQ +2).": "🕵️ El rumor era cierto: {0} está lesionado y te preparaste justo para eso (IQ +2).",
  "🕵️ Söylenti blöftü: {0} sapasağlam. Planın boşa çıktı (IQ -2).": "🕵️ El rumor era un farol: {0} está perfecto. Tu plan falló (IQ -2).",
