  "Memleketinde bir maç kazan ya da popülerlik 70.": "Gana una pelea en tu ciudad o llega a popularidad 70.",
  "🏠 {0} takımının maçında dev bir pankart açıldı: senin yüzün.": "🏠 En el partido del equipo de {0} desplegaron una pancarta gigante: tu cara.",
  "Meydanda heykelin": "Tu estatua en la plaza",
  "UCC şampiyonu ol ya da Hall of Fame'e gir.": "Sé campeón de la UCC o entra en el Salón de la Fama.",
  "🏠 {0} meydanına bronz heykelin dikildi. Kemerli, kollar havada.": "🏠 Levantaron tu estatua de bronce en la plaza de {0}. Con cinturón y los brazos en alto.",
  "Eski salonun yeni minderleri, yeni torbaları ve senin adını taşıyan tabelasıyla açıldı. Çocuklar sıraya girdi. Popülerlik +3, motivasyon +1 (${0}).": "Tu viejo gimnasio reabrió con tatamis y sacos nuevos y un cartel con tu nombre. Los niños hacen cola. Popularidad +3, motivación +1 (${0}).",
  "Meydanda yürüyemedin bile; herkes fotoğraf istedi. Annenin yemeği her şeye değdi. Motivasyon +1, sağlık +5, popülerlik +1.": "Ni siquiera pudiste cruzar la plaza: todos querían una foto. La comida de tu madre lo valió todo. Motivación +1, salud +5, popularidad +1.",
  "Salonda çocuklara bir antrenman verdin, akşam ailenle sofraya oturdun. Motivasyon +1, sağlık +5.": "Diste un entrenamiento a los niños del gimnasio y cenaste con tu familia. Motivación +1, salud +5.",
  "Eski sokaklarda dolaştın, annenin çorbası her şeyi iyileştirdi. Motivasyon +1, sağlık +5.": "Paseaste por las viejas calles y la sopa de tu madre lo curó todo. Motivación +1, salud +5.",
