  "Dostum": "Mi amigo",
  "Kamera yokken de bu kadar cesur musun? Kafeste göreceğiz.": "¿Eres tan valiente cuando no hay cámaras? Lo veremos en la jaula.",
  "Senin videolarını izledim. Açığını buldum bile. 😴": "Vi tus vídeos. Ya encontré tu punto débil. 😴",
  "Ailene söyle, maçı izlemesinler. Üzülmesinler.": "Dile a tu familia que no vea la pelea. Que no sufran.",
  "Basın toplantısında gülüyordun. Kafeste gülemeyeceksin.": "Te reías en la rueda de prensa. En la jaula no te vas a reír.",
  "Bu maçtan sonra kimse adını hatırlamayacak.": "Después de esta pelea nadie recordará tu nombre.",
  "Selam. Kampın iyi geçsin, sağlıklı gel. Kafeste en iyi hâllerimizle karşılaşalım. 🤝": "Hola. Que tengas un buen campamento y llegues sano. Veámonos en nuestra mejor versión. 🤝",
  "Kariyerini uzun zamandır izliyorum. Bu maç ikimiz için de büyük fırsat. Başarılar.": "Sigo tu carrera desde hace tiempo. Esta pelea es una gran oportunidad para los dos. Suerte.",
  "Basında ne derlerse desinler, sana saygım var. Maç günü görüşürüz.": "Diga lo que diga la prensa, te respeto. Nos vemos el día de la pelea.",
  "Görüldü bırak": "Dejar en visto",
  "Sert cevap ver 🔥": "Responder duro 🔥",
  "Ekran görüntüsünü paylaş 📸": "Publicar captura 📸",
  "Cevap vermedin. Sinirini kampa sakladın: motivasyon +1.": "No respondiste. Guardaste la rabia para el campamento: motivación +1.",
  "DM kavgası": "Pelea por DM",
  "Mesajlaşma kızıştı, kulise sızdı. Maçın gündemi yükseldi. Takipçi {0}.": "El intercambio se calentó y se filtró. Creció el interés por la pelea. Seguidores {0}.",
  "İfşa": "Exhibido",
  "Ekran görüntüsü yayıldı, herkes rakibin tehdidini konuşuyor. Takipçi {0}.": "La captura se viralizó, todos hablan de la amenaza. Seguidores {0}.",
  "Saygıyla karşılık ver 🤝": "Responder con respeto 🤝",
  "Alay et 😏": "Burlarse 😏",
  "Karşılıklı saygı. İçin rahat, kampa odaklandın: motivasyon +1, popülerlik +1.": "Respeto mutuo. Mente tranquila, enfocado en el campamento: motivación +1, popularidad +1.",
  "Alaycı DM": "DM burlón",
  "Rakip mesajı paylaştı: “Saygı gösterdim, karşılığı bu.” Gündem yükseldi ama bazı hayranlar soğudu. Takipçi {0}.": "Tu rival lo publicó: “Mostré respeto y esto recibí.” Subió el interés pero algunos fans se enfriaron. Seguidores {0}.",
  "Promotör ofisi": "Oficina del promotor",
  "Maçı satmamız lazım. Önümüzdeki hafta 3 şehirde basın turu ayarlayabiliriz. Yorucu ama bilet satışını uçurur. Var mısın?": "Tenemos que vender esta pelea. Podemos montar una gira de prensa en 3 ciudades la semana que viene. Cansa, pero dispara la taquilla. ¿Te apuntas?",
  "Varım, tura çıkalım": "Me apunto, vamos de gira",
  "Kampı bölmem": "No interrumpo el campamento",
  "Basın turu": "Gira de prensa",
  "Tur olay oldu, biletler kapışılıyor. Ama yol yorgunluğu kampı biraz bozdu: motivasyon -1. Takipçi {0}.": "La gira fue un éxito, las entradas vuelan. Pero el viaje te desgastó: motivación -1. Seguidores {0}.",
  "Promotör homurdandı ama kampına dokunmadın: motivasyon +1.": "El promotor refunfuñó, pero protegiste tu campamento: motivación +1.",
  "Kamp başlamadan bu akşam baş başa bir yemek? Sonra haftalarca yüzünü göremeyeceğim. ❤️": "¿Una cena a solas esta noche antes del campamento? Luego no te veré en semanas. ❤️",
  "Tabii, rezervasyon benden": "Claro, yo reservo",
  "Maçtan sonra telafi ederim": "Te lo compenso después de la pelea",
  "Güzel bir akşamdı. Kafan rahat kampa girdin: motivasyon +1 (−{0}).": "Una noche preciosa. Entras al campamento tranquilo: motivación +1 (−{0}).",
  "“Söz mü?” dedi. Söz verdin. Maçtan sonra unutma.": "“¿Prometido?” Lo prometiste. No lo olvides después de la pelea.",
  "Annem": "Mamá",
  "Oğlum yine maçın varmış, komşudan duydum. Yemeğini düzgün ye, kilo vereceğim diye kendini aç bırakma. Dua ediyorum.": "Me enteré por la vecina de que tienes otra pelea. Come bien, no te mates de hambre por el peso. Rezo por ti.",
  "Baban maçı büyük ekranda izleyecekmiş, bütün mahalleyi çağırdı. Dikkat et kendine yavrum.": "Tu padre la verá en pantalla grande, invitó a todo el barrio. Cuídate, cariño.",
  "Hemen ara 📞": "Llamar ya 📞",
  "“Merak etme anne” yaz": "Escribir “No te preocupes, mamá”",
  "Yarım saat konuştunuz. Sesini duymak iyi geldi: motivasyon +1.": "Hablasteis media hora. Oír su voz te hizo bien: motivación +1.",
  "“Tamam yavrum, Allah utandırmasın” yazdı. ❤️": "Escribió: “Vale, cariño, que Dios te acompañe.” ❤️",
  "Rakibinin stilini taklit edebilirim. Bu akşam salon kapanınca ekstra spar yapalım mı? 🥊": "Puedo imitar el estilo de tu rival. ¿Sparring extra esta noche cuando cierre el gimnasio? 🥊",
  "Yapalım": "Vamos",
  "Bu akşam dinlenmem lazım": "Necesito descansar esta noche",
  "Sert ama faydalı bir spar. Bağınız güçlendi, biraz yıprandın (sağlık −3).": "Sparring duro pero útil. Vuestro vínculo creció, te desgastaste un poco (salud −3).",
  "“Peki kanka” yazdı. Biraz bozulmuş gibi.": "Escribió “Vale, hermano.” Parece algo molesto.",
  "Şanslıydın. Bunu ikimiz de biliyoruz. Rövanşta gerçeği göreceksin.": "Tuviste suerte. Los dos lo sabemos. En la revancha verás la verdad.",
  "Bu gece daha iyiydin, tebrik ederim. Bir gün rövanş isterim ama önce kendimi toparlayacağım. 🤝": "Fuiste mejor esta noche, enhorabuena. Algún día querré la revancha, pero antes me recuperaré. 🤝",
  "Saygılar, iyi dövüştün": "Respeto, buena pelea",
  "Sıraya gir 😎": "Ponte a la cola 😎",
  "Ne zaman istersen": "Cuando quieras",
  "Mesajı paylaştı: “Gerçek bir şampiyon adayı.” Popülerlik +1.": "Lo compartió: “Un auténtico aspirante al título.” Popularidad +1.",
  "Ekran görüntüsü taraftar sayfalarında dolaşıyor. Takipçi {0}.": "La captura circula por las páginas de fans. Seguidores {0}.",
  "Rekabet kızışıyor. Bir gün yine karşılaşırsanız ortalık yanar.": "La rivalidad se calienta. Si os volvéis a ver, arderá todo.",
  "Hocam": "Entrenador",
  "Kafana takma. Yarın sabah salona erken gel, maçı birlikte izleyelim. Neyi yanlış yaptığımızı ben de görmek istiyorum.": "No le des vueltas. Ven temprano al gimnasio mañana, veremos la pelea juntos. Yo también quiero ver qué hicimos mal.",
