  "Maçı kare kare izlediniz. Hocanla bağın güçlendi.": "Visteis la pelea fotograma a fotograma. Tu vínculo con el entrenador creció.",
  "Biraz uzaklaştın, iyi geldi: motivasyon +1. Hocan biraz kırıldı.": "Alejarte un poco te vino bien: motivación +1. Tu entrenador se dolió un poco.",
  "Gurur duydum. Ama şımarmak yok, pazartesi idmandayız. 😄": "Estoy orgulloso. Pero nada de creérselo, el lunes entrenamos. 😄",
  "Her şey senin sayende hocam": "Todo es gracias a ti, entrenador",
  "Pazartesi ilk ben gelirim": "El lunes llego el primero",
