  "Kemeri almak zor, tutmak daha zor. Hoş geldin şampiyon. Bir gün kahve içelim, anlatacak çok şeyim var.": "Ganar el cinturón es difícil, mantenerlo más. Bienvenido, campeón. Tomemos un café algún día, tengo mucho que contarte.",
