  "Hey şampiyon, büyük hayranınım! Bir sonraki maçına gelmek istiyorum. Bilet ayarlayabilir misin? 🙏": "¡Hola campeón, soy tu gran fan! Quiero ir a tu próxima pelea. ¿Me consigues una entrada? 🙏",
  "Ön sıra benden 🎟️": "Primera fila, invito yo 🎟️",
  "Menajerime yaz": "Escríbele a mi mánager",
  "Kafes kenarında kameralar onu gösterecek, adın her yerde: popülerlik +1 (−{0}). Takipçi {1}.": "Las cámaras lo mostrarán junto a la jaula, tu nombre está en todas partes: popularidad +1 (−{0}). Seguidores {1}.",
  "Menajerin halletti. Kibar ama mesafeli.": "Tu mánager se encargó. Amable pero distante.",
  "Hafta sonu kısa bir kaçamak? Sahil kasabası, telefonlar kapalı. 🌊": "¿Una escapada de fin de semana? Pueblo costero, móviles apagados. 🌊",
  "Gidelim!": "¡Vamos!",
  "Bu hafta antrenman var": "Esta semana hay entreno",
  "İki gün deniz, güneş ve sessizlik. Sağlık +4, motivasyon +1 (−{0}).": "Dos días de mar, sol y silencio. Salud +4, motivación +1 (−{0}).",
  "“Anlıyorum ama sıradaki tatil benden” yazdı.": "Escribió: “Lo entiendo, pero el próximo viaje lo elijo yo.”",
  "Senin portreni çizdim, üç gece uğraştım! 🎨 Beğenir misin?": "¡Dibujé tu retrato, me llevó tres noches! 🎨 ¿Te gusta?",
  "Hikâyemde paylaşacağım ❤️": "Lo compartiré en mi historia ❤️",
  "Çizim yayıldı, sanatçı da sen de kazandınız. Takipçi {0}.": "El dibujo se difundió, ganasteis tú y el artista. Seguidores {0}.",
  "“Cevap verdi!!” diye herkese göstermiş. 😊": "Se lo enseñó a todos: “¡¡ME RESPONDIÓ!!” 😊",
