  "Rakiplerin, hayranların ve sponsorların maçlar yaklaştıkça yazmaya başlar.": "Rivales, fans y patrocinadores empiezan a escribir cuando se acercan las peleas.",
  "Sen: {0}": "Tú: {0}",
  "Bu mesajın cevap süresi geçti.": "Ya es tarde para responder a este mensaje.",
  "CEVAP SEÇ": "ELIGE RESPUESTA",
  "Sıklet değiştirme": "Cambio de categoría",
  "Striking": "Striking",
  "Low kick": "Low kick",
