  "ŞAMPİYONSUN. SIRADA EFSANELER VAR": "ERES CAMPEÓN. AHORA, LAS LEYENDAS",
  "{0} kemeri aldıktan sonra kadın MMA'sını dünyaya tanıttı. Onun yolunu bölüm bölüm yaşa.": "Tras ganar el cinturón, {0} llevó el MMA femenino al mundo. Vive su camino capítulo a capítulo.",
  "{0} bu kemeri 29-0'lık yenilmez bir rekorla taşıdı. Onun yolunu bölüm bölüm yaşa.": "{0} llevó este cinturón con un récord invicto de 29-0. Vive su camino capítulo a capítulo.",
