  "Şampiyon Paketi ile bütün ödüller reklamsız ve anında gelir. Tek seferlik alım, abonelik yok.": "Con el Pack de Campeón todos los premios llegan al instante y sin anuncios. Compra única, sin suscripción.",
  "BÜTÜN YUVALAR DOLU": "TODAS LAS RANURAS ESTÁN LLENAS",
  "Şampiyon Paketi ile 5 kariyer yuvası: yeni bir hikâyeye başlamak için eskisini silmen gerekmez.": "El Pack de Campeón te da 5 ranuras: no tienes que borrar una historia para empezar otra.",
  "BİR ŞAMPİYONA YAKIŞIR PAKET": "UN PACK DIGNO DE UN CAMPEÓN",
  "Kemeri kazandın. Şampiyon Paketi ile oyunun bütün ekstralarını aç.": "Ganaste el cinturón. Desbloquea todos los extras con el Pack de Campeón.",
  "👑 Şampiyon Paketi ile reklamsız, anında": "👑 Sin anuncios y al instante con el Pack de Campeón",
  "👑 ŞAMPİYON PAKETİ": "👑 PACK DE CAMPEÓN",
  "İstediğin iki dövüşçü, istediğin sıklet, istediğin kadar maç. Kendi efsanelerini de efsanelere karşı dövüştür.": "Los dos luchadores que quieras, en el peso que quieras, cuantas veces quieras. Enfrenta también a tus propias leyendas con las leyendas.",
