  "Kimi yöneteceksin?": "¿A quién controlarás?",
  "Rakibini seç.": "Elige a tu rival.",
  "Kırmızı köşe": "Esquina roja",
  "Mavi köşe": "Esquina azul",
  "Emekli olan dövüşçülerini emeklilik ekranından Efsanelerim'e ekleyebilirsin; burada efsanelere karşı dövüşürler.": "Puedes añadir a tus luchadores retirados a Mis Leyendas desde la pantalla de retiro; aquí pelean contra las leyendas.",
