  "Zirvedeki halleriyle · 5 raunt": "En su mejor momento · 5 asaltos",
  "{0} vs {1}": "{0} vs {1}",
  "İstediğin iki dövüşçü, istediğin sıklet, sınırsız maç. Kendi efsanelerin de burada.": "Los dos luchadores que quieras, en cualquier peso, combates ilimitados. Tus propias leyendas también están aquí.",
