  "Puan: maç +{0}, galibiyet +{1}, bitiriş +{2}, Günün Dövüşü +{3}, Hayalî Maç +{4}, efsane bölümü +{5}": "Puntos: combate +{0}, victoria +{1}, finalización +{2}, Combate del Día +{3}, Combate Soñado +{4}, capítulo de leyenda +{5}",
  "👑 ŞAMPİYON SIRASI": "👑 PISTA DE CAMPEÓN",
  "Şampiyon Paketi ile her sezon 6 ödül daha: efsanevi sezon şortu, kemer, giriş efekti… Ulaştığın basamakların ödülleri hemen açılır.": "Con el Pack de Campeón, 6 premios más cada temporada: pantalón legendario, cinturón, efecto de entrada… Los premios de los niveles alcanzados se desbloquean al instante.",
  "Her ay yeni sezon, yeni tema. Sezon bitince alınmayan ödüller kaybolur; aldıkların dolabında kalır.": "Cada mes, temporada y tema nuevos. Los premios no reclamados desaparecen al terminar; los reclamados se quedan en tu vestidor.",
