  "Rövanşı Kazansaydı": "Si hubiera ganado la revancha",
  "O gece bir türlü aklından çıkmadı. Boyun kilidi, susan salon, kafesin üstünden atlayanlar.": "Aquella noche nunca se te fue de la cabeza. La llave al cuello, el pabellón en silencio, los que saltaban la jaula.",
  "Ama ya her şey başka türlü olsaydı? Ya rövanş gerçekten yapılsaydı?": "¿Y si todo hubiera sido distinto? ¿Y si la revancha se hubiera hecho de verdad?",
  "Khabir Nurmagaliev hâlâ kemerin sahibi. Bu kez onu ayakta tutacak, mesafeyi sen belirleyeceksin.": "Khabir Nurmagaliev sigue siendo el campeón. Esta vez lo mantendrás de pie y marcarás tú la distancia.",
  "Khabir Nurmagaliev'i yen": "Vence a Khabir Nurmagaliev",
  "Hafif sıklete dön: Nurmagaliev kemerin sahibi olarak orada bekliyor.": "Vuelve al peso ligero: Nurmagaliev te espera allí como campeón.",
  "Hafif sıklet kemerini al": "Gana el cinturón del peso ligero",
