  "{0} karşısına kimi çıkaracaksın?": "¿A quién enviarás contra {0}?",
  "Bu kategoride dövüşçün yok. Önce bir kariyer başlat.": "No tienes peleador en esta categoría. Empieza una carrera primero.",
  "Arkadaşının dövüşçüsü yapay zekâyla karşına çıkar. Sen de kodunu paylaş, seninkiyle dövüşsünler.": "El peleador de tu amigo te enfrenta controlado por la IA. Comparte también tu código para que peleen contra el tuyo.",
