  "Kartın zirvesindeki maçları tahmin et. Doğru kazanan para kazandırır; favori olmayanı bilmek daha değerli. Bitiriş ya da kararı da bilirsen ek ödül.": "Pronostica las peleas estelares. Acertar al ganador da dinero, y acertar con el no favorito vale más. Si aciertas también si acaba antes o por decisión, hay extra.",
