  "🔔 {0}. raunt bitti. Puan kartını doldur.": "🔔 Terminó el asalto {0}. Rellena tu tarjeta.",
  "{0} bacaklara daldı, {1} sprawl ile savundu.": "{0} fue a las piernas, {1} se defendió con un sprawl.",
  "{0} rakibini yere indirdi, üstten kontrol ediyor.": "{0} derribó a su rival y controla desde arriba.",
  "{0} kombinasyonlarla öne geçti.": "{0} se adelantó con combinaciones.",
  "Ortada sert bir değişim, ikisi de vurdu.": "Intercambio duro en el centro, los dos conectaron.",
  "💥 {0} yere düştü!": "💥 ¡{0} cae a la lona!",
  "Bitti! {0} ayağa kalkamadı, hakem hemen araya girdi.": "¡Se acabó! {0} no pudo levantarse y el árbitro intervino.",
  "Maçı durdur": "Detener el combate",
  "Devam ettir": "Dejar que siga",
  "Kollarını kaldırmıyor, gözleri boşlukta.": "No levanta los brazos, tiene la mirada perdida.",
  "Yumruklara hiç tepki vermiyor, yüzü açık.": "No reacciona a los golpes, la cara al descubierto.",
  "Elleriyle kapatıyor ama karşılık vermiyor.": "Se cubre con las manos pero no responde.",
  "Dizlerinin üstünde, başını korumaya çalışıyor.": "De rodillas, intenta protegerse la cabeza.",
  "Bacağa sarılıp kalkmaya çalışıyor.": "Se agarra a una pierna e intenta levantarse.",
  "Kafesi tutup doğruluyor, gözleri sana bakıyor.": "Se apoya en la jaula para levantarse y te mira.",
  "Hasar: çok ağır": "Daño: muy grave",
  "Hasar: ağır": "Daño: grave",
  "Hasar: orta": "Daño: moderado",
  "{0} sarsıldı! {1} üstüne yürüyor.": "¡{0} está tocado! {1} va a por él.",
  "Rauntun bitmesine {0}:{1}": "Quedan {0}:{1} del asalto",
  "Seyirci ayakta, “durdur” diye bağıranlar var.": "El público está de pie, algunos gritan «¡páralo!».",
  "Eli rakibinin sırtına iki kez hafifçe dokundu.": "Su mano tocó dos veces la espalda del rival, suavemente.",
  "Kolları gevşedi, artık savaşmıyor.": "Sus brazos se aflojaron, ya no pelea.",
  "Yüzü kızarmış, elleri yavaşlıyor.": "Tiene la cara roja y las manos cada vez más lentas.",
  "Kol açısı tehlikeli, yüzünü buruşturuyor.": "El brazo está en un ángulo peligroso, hace muecas.",
  "Ellerini kenetledi, kilidi açmaya çalışıyor.": "Ha juntado las manos y trata de deshacer la llave.",
  "Kalçasını kaydırıp boynunu kurtarmaya uğraşıyor.": "Mueve la cadera para liberar el cuello.",
  "{0} kilidi kapattı!": "¡{0} cerró la llave!",
  "Köşesinden “dayan!” diye bağırıyorlar.": "Su esquina le grita «¡aguanta!».",
  "Kilit {0} saniyedir sürüyor.": "La llave dura ya {0} segundos.",
  "Bekle, izle": "Espera y observa",
  "Bel altına bir tekme girdi.": "Una patada entró por debajo del cinturón.",
  "Açık eldivenle göze parmak girdi.": "Un dedo entró en el ojo con el guante abierto.",
  "Takedown'ı savunurken kafesi tuttu.": "Se agarró a la jaula al defender el derribo.",
  "Yerdeki rakibin kafasına diz attı.": "Rodillazo a la cabeza del rival en el suelo.",
  "Faul! {0}: {1}": "¡Falta! {0}: {1}",
  "Tekrar izlemede hareket bilinçli görünüyor.": "En la repetición parece intencionado.",
  "Tekrar izlemede kazara olmuş gibi.": "En la repetición parece accidental.",
  "Bu maçta daha önce de faul yaptı.": "Ya cometió una falta antes en este combate.",
  "Bu maçtaki ilk faulü.": "Su primera falta del combate.",
  "{0} yerde kıvranıyor, doktor devam edemeyeceğini söylüyor.": "{0} se retuerce en el suelo; el médico dice que no puede seguir.",
  "{0} toparlanmak için zaman istiyor.": "{0} pide tiempo para recuperarse.",
  "{0} hemen devam etmek istiyor.": "{0} quiere seguir de inmediato.",
  "Sözlü uyarı": "Advertencia verbal",
  "Puan düş": "Restar un punto",
  "Diskalifiye et": "Descalificar",
  "{0} kaşından kanıyor.": "{0} sangra de la ceja.",
  "Kan doğrudan gözüne akıyor, sürekli siliyor.": "La sangre le cae directa al ojo, no deja de limpiarse.",
  "Kaşta küçük bir kesik, kan yanağa sızıyor.": "Un pequeño corte en la ceja, la sangre baja por la mejilla.",
  "Rakibin vuruşlarını göremiyor gibi.": "Parece que no ve venir los golpes.",
