  "Efsane #{0}": "Leyenda #{0}",
  "🏛️ TARİH YAZILDI! {0}: artık tüm zamanların 1 numarası sensin, {1} geride kaldı. +${2}, popülerlik +{3}.": "🏛️ ¡HISTORIA! {0}: ya eres el número 1 de todos los tiempos, por delante de {1}. +${2}, popularidad +{3}.",
  "🏛️ Rekor: {0} listesinde {1} dövüşçüsünü geçtin, sıran #{2}. +${3}, popülerlik +{4}.": "🏛️ Récord: superaste a {1} en la lista «{0}». Eres el #{2}. +${3}, popularidad +{4}.",
  "UCC Tarihi": "Historia de UCC",
  "{0} tarihin 1 numarası: {1}. Bu rekor uzun süre konuşulacak.": "{0}, número 1 de la historia: {1}. Este récord dará que hablar mucho tiempo.",
  "📰 {0}: {1} rekoruna bir adım kaldı!": "📰 {0}: a un paso del récord de {1}.",
  "Nakavtçı": "Noqueador",
  "Yumruğun konuşuyor. Sert vuruşların rakibi daha sık sarsar.": "Tus puños hablan. Tus golpes duros sacuden al rival más a menudo.",
  "Boğucu Güreşçi": "Luchador Asfixiante",
  "Yere inen kalkamıyor. Yerde kilit fırsatın daha sık gelir.": "Quien cae no se levanta. Las opciones de sumisión llegan más a menudo.",
  "Taktisyen": "Táctico",
  "Aklınla dövüşüyorsun. Rakip seni daha geç okur, köşen zaafları daha çabuk bulur.": "Peleas con la cabeza. El rival te lee más tarde y tu esquina halla sus debilidades antes.",
  "Salonu ayağa kaldırıyorsun. Galibiyetler daha çok popülerlik getirir.": "Pones al público en pie. Las victorias dan más popularidad.",
  "{0} Dövüş kimliğin oluştu: {1}! {2}": "{0} Tu identidad de combate ha nacido: {1}! {2}",
  "{0} Kimliğin değişti: artık bir {1}. {2}": "{0} Tu identidad ha cambiado: ahora, {1}. {2}",
  "{0} için herkes aynı şeyi söylüyor: {1}.": "Todos dicen lo mismo de {0}: {1}.",
  "🗞️ {0}: \"Sert vurduğunu biliyorum. Çenemi çalıştırdım.\"": "🗞️ {0}: \"Sé que pegas duro. He trabajado la mandíbula.\"",
  "🗞️ {0} kampında tek konu: nakavtçıya karşı nasıl ayakta kalınır?": "🗞️ Un solo tema en el campamento de {0}: cómo seguir en pie ante un noqueador.",
  "🗞️ {0} bütün kampı güreş savunmasıyla geçirdi: \"Beni yere indiremeyecek.\"": "🗞️ {0} pasó todo el campamento defendiendo derribos: \"No me vas a derribar.\"",
  "🗞️ {0}: \"Herkes yerde boğuluyor, ben boğulmayacağım.\"": "🗞️ {0}: \"Todos se asfixian en el suelo. Yo no.\"",
  "🗞️ {0}: \"Çok düşünüyor. Ona düşünecek vakit bırakmayacağım.\"": "🗞️ {0}: \"Piensas demasiado. No te daré tiempo para pensar.\"",
  "🗞️ {0} kampı senin maçlarını kare kare izliyor.": "🗞️ El campamento de {0} estudia tus combates fotograma a fotograma.",
  "🗞️ {0}: \"Kafes sirk değil. Şovunu bitireceğim.\"": "🗞️ {0}: \"La jaula no es un circo. Acabaré con tu show.\"",
  "🗞️ {0} basına konuştu: \"Bu kadar gösteriş yeter.\"": "🗞️ {0} dijo a la prensa: \"Ya basta de espectáculo.\"",
