  "Münhasırlık": "Exclusividad",
  "Organizasyon ister: ücret +%15, ama başka hiçbir teklife bakamazsın.": "La organización la pide: bolsa +15 %, pero no puedes mirar ninguna otra oferta.",
  "Sakatlık güvencesi": "Protección por lesión",
  "Sakatken kadrodan çıkarılamaz, maaşın yarısı ödenir.": "No puede ser cortado mientras esté lesionado y cobra la mitad de la bolsa.",
