  "Sıfırdan": "Desde cero",
  "Elinde tek bir sokak dövüşçüsü ve kirası ödenmemiş bir bodrum ofis var. Her şey sana bağlı.": "Solo tienes un peleador callejero y una oficina en el sótano con el alquiler sin pagar. Todo depende de ti.",
  "Tek yıldız": "Una estrella",
  "Kadronda bir UCC şampiyonu var, ama sözleşmesi bitmek üzere ve rakip ajanslar kapıda. Onu kaybetme.": "Tienes un campeón de UCC en tu plantilla, pero su contrato está por vencer y las agencias rivales están en la puerta. No lo pierdas.",
  "Batık ajansı kurtar": "Salva la agencia en quiebra",
  "Önceki menajerden borç ve sana küskün üç dövüşçü devraldın. Bir yılda borcu kapat.": "Heredaste deudas del mánager anterior y tres peleadores resentidos contigo. Salda la deuda en un año.",
  "Yurt dışı yetenekleri": "Talento extranjero",
  "Brezilya ve Dağıstan'dan iki genç yetenek getirdin. Vize, dil ve gurbet sorunlarıyla yıldız yap.": "Trajiste a dos jóvenes talentos de Brasil y Daguestán. Conviértelos en estrellas entre visados, idiomas y nostalgia.",
  "Menajer": "Mánager",
  "{0} Yönetim": "{0} Management",
  "İlk yılında bir dövüşçünü bölgesel lige taşı.": "Lleva a uno de tus peleadores a la liga regional en tu primer año.",
  "Abi, otoparktaki dövüşleri bırakıp gerçek bir kafese çıkmak istiyorum. Sana güveniyorum. Beni bir yere götür.": "Hermano, quiero dejar las peleas de estacionamiento y subir a una jaula de verdad. Confío en ti. Llévame a algún lado.",
  "{0} ile yeni sözleşme imzala, onu rakip ajanslara kaptırma.": "Firma un nuevo contrato con {0} y no lo pierdas ante agencias rivales.",
  "Sözleşmem bir maç sonra bitiyor. Telefonum susmuyor, herkes beni istiyor. Sen beni neden tutmalıyım, onu düşünüyorum.": "Mi contrato termina tras una pelea más. Mi teléfono no para, todos me quieren. Estoy pensando por qué debería quedarme contigo.",
  "Bir yıl içinde borcu kapat (para sıfırın üstüne çıksın).": "Salda la deuda en un año (que tu dinero quede por encima de cero).",
  "Ajansınızın {0} borcu bulunmaktadır. Kira ödemeleri devam ettikçe borç büyüyecektir.": "Su agencia debe {0}. La deuda crecerá mientras sigan venciendo los alquileres.",
  "Eski menajer paramızı yedi. Sen farklı mısın, göreceğiz.": "El mánager anterior se comió nuestro dinero. Veremos si tú eres diferente.",
  "İki yeteneğinden birini büyük lige taşı.": "Lleva a uno de tus dos talentos a la liga mayor.",
  "Burası çok soğuk, abi. Annem her gün arıyor. Ama söz verdim, kemerle döneceğim.": "Aquí hace mucho frío, hermano. Mi madre llama todos los días. Pero lo prometí, vuelvo con el cinturón.",
  "Ofis dolu. Yeni dövüşçü için ofisi büyüt ya da birini bırak.": "La oficina está llena. Amplía la oficina para un nuevo peleador o deja ir a alguien.",
  "İmza parası için yeterli paran yok.": "No tienes suficiente dinero para la prima de fichaje.",
  "{0} teklifini reddetti ve {1} ile anlaştı.": "{0} rechazó tu oferta y firmó con {1}.",
  "Hafta {0}: {1} kadroya katıldı (%{2}).": "Semana {0}: {1} se unió a la plantilla ({2} %).",
  "✍️ {0} ajansına katıldı!": "✍️ ¡{0} se unió a la agencia!",
  "Hafta {0}: {1} ile yollar ayrıldı.": "Semana {0}: te separaste de {1}.",
  "Hafta {0}: Çıkış maddesi işledi, {1} bedelsiz ayrıldı.": "Semana {0}: se activó la cláusula de salida, {1} se fue gratis.",
  "Hafta {0}: {1} sözleşmesini {2} bedelle feshetti.": "Semana {0}: {1} rescindió el contrato por {2}.",
  "{0}! Rüya gibi. Bunu sana borçluyum.": "¡{0}! Es como un sueño. Te lo debo.",
  "Annemi aradım, ağladı. {0} sözleşmesi, inanamıyorum.": "Llamé a mi madre, lloró. Un contrato con {0}, no lo puedo creer.",
  "Daha yeni başlıyoruz. {0}'de herkes adımı öğrenecek.": "Esto apenas empieza. En {0} todos aprenderán mi nombre.",
  "Hafta {0}: {1} için {2} ile {3} maçlık sözleşme ({4}/maç).": "Semana {0}: contrato de {3} peleas para {1} con {2} ({4}/pelea).",
  "📝 {0} artık {1} dövüşçüsü.": "📝 {0} ya es peleador de {1}.",
  "🗓️ {0} – {1} maçı {2}. haftada.": "🗓️ {0} vs {1} en la semana {2}.",
  "{0}: “Teklifimiz ortada. Dinliyoruz.”": "{0}: “Nuestra oferta está sobre la mesa. Te escuchamos.”",
  "{0}: “Son teklifimiz {1}. İmzala ya da yolumuza bakalım.”": "{0}: “Nuestra última oferta es {1}. Firma o cada uno por su lado.”",
  "{0}: “Tamam, {1} olsun.”": "{0}: “Está bien, que sea {1}.”",
  "{0}: “Peki. Maç başı {1}.”": "{0}: “De acuerdo. {1} por pelea.”",
  "{0}: “Zorluyorsun ama olur: {1}.”": "{0}: “Estás apretando, pero vale: {1}.”",
  "{0}: “Bütçeyi zorluyorsun. {1} yapabiliriz.”": "{0}: “Estás forzando el presupuesto. Podemos hacer {1}.”",
  "{0}: “Kazanırsa hak eder. Bonus {1}.”": "{0}: “Si gana, se lo merece. Bono de {1}.”",
  "{0}: “Münhasırlık mı? Seve seve. Ücrete %15 ekliyoruz.”": "{0}: “¿Exclusividad? Encantados. Sumamos un 15 % a la bolsa.”",
  "{0}: “{1}, kabul. Sözleşmeye yazıyoruz.”": "{0}: “{1}, aceptado. Lo ponemos en el contrato.”",
  "{0}: “Çıkış maddesi mi? Dövüşçüne yatırım yapıyoruz, kaçmasına izin vermeyiz.”": "{0}: “¿Cláusula de salida? Invertimos en tu peleador, no dejaremos que se escape.”",
  "{0}: “{1} olmaz. Başka bir şey?”": "{0}: “{1}, no. ¿Algo más?”",
