  "KEMER BİZİM! Bu gece ikimizin. Teşekkürler, ortak.": "¡EL CINTURÓN ES NUESTRO! Esta noche es de los dos. Gracias, socio.",
  "Çocukken hayalini kurduğum kemer belimde. Bunu sen mümkün kıldın.": "El cinturón con el que soñaba de niño está en mi cintura. Tú lo hiciste posible.",
