  "Bu gece senin kariyerini bitireceğim.": "Esta noche acabo con tu carrera.",
  "Herkes beni konuşacak, sen de dahil.": "Todos van a hablar de mí, tú incluido.",
  "O kemer zaten benim, sadece takacağım.": "Ese cinturón ya es mío, solo me lo voy a poner.",
  "Sen sadece bir basamaksın.": "Solo eres un escalón.",
  "Ekibim arkamda. Hazırım.": "Mi equipo me respalda. Estoy listo.",
  "Saygım var ama o kafeste kardeş yok.": "Te respeto, pero en esa jaula no hay hermanos.",
  "Köşemi dinleyeceğim, gerisi gelir.": "Escucharé a mi esquina, lo demás vendrá solo.",
  "Erken bitireceğim, akşam yemeğine yetişmem lazım.": "Lo terminaré rápido, tengo que llegar a cenar.",
  "Antrenman mı? Yeteneğim yeter.": "¿Entrenar? Mi talento basta.",
  "Uzatmayalım şu işi.": "No alarguemos esto.",
