  "Gülümse, bu fotoğraf manşette.": "Sonríe, esta foto va a portada.",
  "Bu maç benim maaşımı ikiye katlayacak.": "Esta pelea va a duplicar mi sueldo.",
  "Sponsorlarım bakıyor, iyi görünmem lazım.": "Mis patrocinadores están mirando, tengo que verme bien.",
  "Ödemeyi aldım, şimdi şovu izle.": "Ya cobré, ahora disfruta el show.",
