  "Menajerin seni kurbanlığa getirmiş.": "Tu mánager te trajo aquí como sacrificio.",
  "Bu gece ışıkları söndüreceğim.": "Esta noche apago las luces.",
  "Tek seferlik alım: sınırsız ajans kariyeri, UCC sözleşmeleri, şampiyonlar ve Yılın Menajeri ödülü.": "Compra única: carreras de agencia ilimitadas, contratos de UCC, campeones y el premio al Mánager del Año.",
