  "Bu sefer kafese sen çıkmıyorsun. Dövüşçülerin kariyeri, parası ve sağlığı senin telefonunda.": "Esta vez no eres tú quien sube a la jaula. La carrera, el dinero y la salud de tus peleadores están en tu teléfono.",
  "Telefonun hiç susmaz: dövüşçüler, patronlar, gazeteciler ve rakip menajerler. Her cevabın bir sonucu var.": "Tu teléfono nunca calla: peleadores, jefes, periodistas y mánagers rivales. Cada respuesta tiene consecuencias.",
  "Organizasyonların gizli bütçesine karşı pazarlık yap; rövanş, çıkış ve sakatlık maddeleri yıllar sonra işine yarar.": "Negocia contra el presupuesto oculto de las organizaciones; las cláusulas de revancha, salida y lesión dan frutos años después.",
  "Yetenek avına çık, gençleri komisyon pazarlığıyla imzala, rakip ajanslardan önce davran.": "Sal a buscar talento, ficha jóvenes negociando la comisión y adelántate a las agencias rivales.",
  "İki dövüşçün aynı kemere yürürse? Organizasyon onları birbirine eşlemek isteyecek.": "¿Y si dos de tus peleadores van por el mismo cinturón? La organización querrá enfrentarlos.",
  "Doktor uyarır, para çağırır. Dövüşçünün sağlığı mı, maaş günü mü?": "El médico advierte, el dinero llama. ¿La salud de tu peleador o el día de pago?",
