  "YOL EVRENİ": "UNIVERSO YOL",
  "Bütün modların aynı dünyada geçiyor. Kariyerindeki dövüşçülerin Menajer Modu'nda rakip olarak teklif edilir; Menajer Modu'ndaki dövüşçülerin de büyük ligde ve UCC'de kariyerinin karşısına çıkar.": "Todos tus modos comparten un mismo mundo. Tus peleadores de carrera aparecen como rivales en el Modo Mánager, y los peleadores de tu Modo Mánager se cruzan con tu carrera en las ligas mayores y en la UCC.",
  "ÇAPRAZ MAÇ": "CRUCES",
  "ÇAPRAZ MAÇLAR": "PELEAS CRUZADAS",
  "Henüz modlar arası maç yok. Büyük lige çıktıkça ve Menajer Modu'nda teklifler geldikçe dövüşçülerin karşılaşacak.": "Aún no hay peleas cruzadas. Cuando llegues a las ligas mayores y lleguen ofertas en el Modo Mánager, tus peleadores se cruzarán.",
  "Bağlantı için iki tarafta da dövüşçü gerekir: aktif bir kariyer ve Menajer Modu'nda aynı sıklette bir dövüşçü.": "Necesitas peleadores en ambos lados: una carrera activa y un peleador de la misma categoría en el Modo Mánager.",
