  "Henüz kariyerin yok.": "Aún no tienes carreras.",
  "MENAJER MODU DÖVÜŞÇÜLERİN": "TUS PELEADORES DEL MODO MÁNAGER",
  "Menajer Modu'nda ajans kurup dövüşçü imzaladığında burada görünürler.": "Cuando abras una agencia y fiches peleadores en el Modo Mánager, aparecerán aquí.",
