  "Kampın nasıl geçti? Bu maç için ne değiştirdin?": "¿Cómo fue el campamento? ¿Qué cambiaste para esta pelea?",
  "“Her gün biraz daha iyi olmaya çalıştık. Gerisini kafeste göreceğiz.”": "“Intentamos mejorar un poco cada día. El resto lo veremos en la jaula.”",
  "“Ekibime güveniyorum. İşimizi yaptık.”": "“Confío en mi equipo. Hicimos nuestro trabajo.”",
  "“Bu kampta onu üç kez yendim, sparringde. Cumartesi dördüncüsü.”": "“Le gané tres veces en este campamento, en sparring. El sábado será la cuarta.”",
  "“Hiç bu kadar hazır olmadım. Şanssızlığı onun.”": "“Nunca he estado tan preparado. Mala suerte para él.”",
  "“Değişen tek şey diyetim. Özledim pideyi.”": "“Lo único que cambió es mi dieta. Echo de menos la pizza.”",
  "“Hocam bağırmaktan sesini kaybetti, demek ki iyi geçti.”": "“Mi entrenador se quedó afónico de gritar, así que fue bien.”",
  "“Her şey sizin için. İyi ki varsınız.”": "“Todo es por vosotros. Qué suerte teneros.”",
  "“Desteğinizi hissediyorum. Sizi mahcup etmeyeceğim.”": "“Siento vuestro apoyo. No os voy a fallar.”",
  "“Tribünleri doldurun, bir şov izleyeceksiniz.”": "“Llenad las gradas, vais a ver un espectáculo.”",
  "“Bayramı şimdiden hazırlayın.”": "“Id preparando la fiesta.”",
  "“Bilet alanlar arkada oturmasın, önde daha çok kan var.”": "“Los que tengáis entrada, no os sentéis atrás, delante hay más sangre.”",
  "“Cumartesiden sonra hepinize çay benden.”": "“Después del sábado, invito yo a todos.”",
  "{0} senin en zayıf yanını bulduğunu söylüyor. Ne diyeceksin?": "{0} dice que encontró tu mayor debilidad. ¿Qué respondes?",
  "“Herkesin zayıf yanı vardır. Ben de kendiminkini çalıştım.”": "“Todos tenemos debilidades. Yo trabajé las mías.”",
  "“Bulmuşsa iyi, ben de onunkini buldum.”": "“Bien si la encontró, yo también encontré la suya.”",
  "“Zayıf yanım mı? Onu bulmak için önce ayakta kalması lazım.”": "“¿Mi debilidad? Para encontrarla primero tiene que seguir de pie.”",
  "“Bulsun. Cumartesi aramaya vakti olmayacak.”": "“Que la busque. El sábado no tendrá tiempo.”",
  "“Zayıf yanım tatlı. Kafeste tatlı yok, sorun yok.”": "“Mi debilidad son los dulces. En la jaula no hay dulces, así que no pasa nada.”",
  "“Bunu söylemesi bile bir zayıflık aslında.”": "“Decir eso ya es una debilidad.”",
  "Ne zaman emekli olmayı düşünüyorsun?": "¿Cuándo piensas retirarte?",
  "“Vücudum söyleyecek. Şimdilik dinliyor.”": "“Mi cuerpo me lo dirá. Por ahora escucha.”",
  "“Daha yolun başındayım gibi hissediyorum.”": "“Siento que acabo de empezar.”",
  "“Bütün rekorları kırınca. Yani biraz daha var.”": "“Cuando bata todos los récords. O sea, falta un poco.”",
  "“Rakip kalmadığında. Takvimi ona göre ayarlayın.”": "“Cuando no queden rivales. Organizad el calendario así.”",
  "“Emeklilik maaşı yeterse yarın. Yetmiyor, devam.”": "“Mañana, si la pensión alcanza. No alcanza, así que sigo.”",
  "“Torunum beni yenince.”": "“Cuando mi nieto me gane.”",
  "Bu maçtan ne kadar kazanacaksın?": "¿Cuánto vas a ganar con esta pelea?",
  "“Para önemli ama kemer daha önemli.”": "“El dinero importa, pero el cinturón importa más.”",
  "“Hak ettiğim kadar. Gerisi menajerin işi.”": "“Lo que merezco. El resto es cosa de mi mánager.”",
  "“Yetmez. Bir sonrakinde iki katını isteyeceğim.”": "“No es suficiente. La próxima pediré el doble.”",
  "“Onun bütün kariyerinde kazandığından fazla.”": "“Más de lo que él ganó en toda su carrera.”",
  "“Yeni bir araba alacak kadar. Park yeri bulamayacak kadar değil.”": "“Para comprar un coche nuevo. No para encontrar aparcamiento.”",
  "“Annem duyunca hemen fatura listesi yolladı.”": "“Mi madre se enteró y me mandó las facturas enseguida.”",
