  "{0}: “Bu cümleyi çerçeveletip duvarına as, son kez söylüyorsun.”": "{0}: “Enmarca esa frase y cuélgala en tu pared, es la última vez que la dices.”",
  "{0}: “Gülmek serbest, cumartesi ağlamak da.”": "{0}: “Reír es gratis, el sábado llorar también.”",
