  "{0} kameraya döndü: “Bakışlar dövüşmez.”": "{0} se giró a la cámara: “Las miradas no pelean.”",
  "{0} sinirle omuz silkti, köşesine yürüdü.": "{0} se encogió de hombros con rabia y se fue a su esquina.",
  "{0}: “Bu gece kazandın, cumartesi benim.”": "{0}: “Hoy ganaste tú, el sábado es mío.”",
  "{0} kameralara döndü: “Gördünüz mü, şimdiden korkuyor.”": "{0} se giró a las cámaras: “¿Lo veis? Ya tiene miedo.”",
  "{0} giderken arkasından seslendi: “Cumartesi daha kötü olacak!”": "{0} gritó al irse: “¡El sábado será peor!”",
