  "Maç MMA karnene işlenmez. İki hafta sürer; aldığın hasarın bir kısmı sağlığına yansır.": "El combate no cuenta en tu récord de MMA. Dura dos semanas; parte del daño recibido afecta tu salud.",
  "DÖVÜŞ SPORLARI": "DEPORTES DE COMBATE",
  "MMA maçlarının arasında başka sporların ringine çık: kendi kuralları, kendi kemerleri.": "Entre combates de MMA, sube al ring de otros deportes: sus reglas, sus cinturones.",
  "Ligler": "Ligas",
  "Ligler profesyonel kariyerde açılır.": "Las ligas se abren en tu carrera profesional.",
  "Işıklar kararıyor. Halatların arasından ringe giriyorsun; hakem ikinizi ortaya çağırıyor.": "Las luces bajan. Pasas entre las cuerdas; el árbitro os llama al centro.",
  "Halka altın olunca KAÇ. DİREKT hazırlığı keser; yorulunca GARD al.": "ESQUIVA cuando el aro se vuelva dorado. El DIRECTO corta su preparación; cuando te canses, GUARDIA.",
  "Boks şampiyonu": "Campeón de boxeo",
  "Boks {0}-{1} · {2} hafta": "Boxeo {0}-{1} · {2} sem.",
