  "Mindere çık": "Sube al tapiz",
  "YER": "SUELO",
  "ZEKÂ": "IQ",
  "Işıklar kararıyor. Mindere çıkıyorsun; hakem ikinizi ortaya çağırıyor, tokalaşıyorsunuz.": "Las luces bajan. Subes al tapiz; el árbitro os llama al centro y os dais la mano.",
  "Dalışı kes": "Corta el derribo",
  "Pozisyon al": "Toma posición",
  "Tutun, baskıyı kes": "Agárrate, corta la presión",
  "SPRAWL": "SPRAWL",
  "İLERLET": "AVANZAR",
  "TUTUNUYOR": "SE AGARRA",
  "TUTUNDUN!": "¡AGUANTASTE!",
  "POZİSYON!": "¡POSICIÓN!",
  "BASKI ALTINDASIN": "BAJO PRESIÓN",
  "TUŞ!": "¡TOCADO!",
  "TUŞ OLDUN": "TE TOCARON",
  "İLERLET ile pozisyonu doldur; tam hâkimiyette sırtını yapıştır: TUŞ. ⤴️ görünce KONTROL.": "Llena la posición con AVANZAR; con control total pega su espalda: TOCADO. ¿Ves ⤴️? CONTROL.",
  "İLERLET ile pozisyon al, sonra SUB. ⤴️ ya da 🔒 görünce KONTROL.": "AVANZA para tomar posición y luego SUB. ¿Ves ⤴️ o 🔒? CONTROL.",
  "👊 baskı gelirken GARD ile tutun, sonra KURTUL.": "👊 Cuando llegue la presión, agárrate con GUARDIA y luego ESCAPA.",
  "Dalış hazırlığında (halka altın) SPRAWL. İNDİR ile puan al; yerde İLERLET ile pozisyonu büyüt.": "Cuando prepare el derribo (aro dorado), SPRAWL. Puntúa con DERRIBAR; en el suelo, mejora la posición con AVANZAR.",
  "Boks · Muay Thai · Güreş": "Boxeo · Muay Thai · Lucha",
  "Sınav haftası. Hocan aynı akşam ek antrenman koymuş.": "Semana de exámenes. Tu entrenador puso una sesión extra esa misma tarde.",
  "Ders çalış": "Estudia",
  "Karnen parladı; ailen gururlu, kafan rahat.": "Notas brillantes; tu familia está orgullosa y tienes la cabeza tranquila.",
  "Antrenmana git": "Ve a entrenar",
  "Salonda son çıkan sendin. Hocan fark etti.": "Fuiste el último en salir del gimnasio. Tu entrenador se dio cuenta.",
  "Hocan seni ilk kez büyüklerle çalıştırmak istiyor.": "Por primera vez, tu entrenador quiere que entrenes con los mayores.",
  "Çok dayak yedin ama korkmamayı öğrendin.": "Recibiste mucho, pero aprendiste a no tener miedo.",
  "Yaşıtlarınla kal": "Quédate con los de tu edad",
  "Tekniğini sakin sakin oturttun.": "Pulista tu técnica con calma.",
  "Evde para sıkıntısı var. Yaz için bir işe girmen isteniyor.": "En casa falta dinero. Te piden que trabajes en verano.",
  "Çalış": "Trabaja",
  "Pazarda kasa taşıdın; hem cebine para girdi hem de kondisyonun arttı.": "Cargaste cajas en el mercado: dinero en el bolsillo y mejor resistencia.",
  "Kampa git": "Ve al campamento",
  "Ailen idare etti; sen de yaz kampında bir üst seviyeye çıktın.": "Tu familia se las arregló y tú subiste de nivel en el campamento de verano.",
  "Antrenman videon okulda elden ele dolaşıyor.": "Tu vídeo entrenando circula por el colegio.",
  "Hesap aç, paylaş": "Abre una cuenta y publícalo",
  "İlk takipçilerin geldi. Mahallede tanınıyorsun.": "Llegaron tus primeros seguidores. En el barrio ya te conocen.",
  "Boş ver, çalış": "Olvídalo, entrena",
  "Ekrana değil kum torbasına baktın.": "Miraste al saco, no a la pantalla.",
  "Şehrin büyük kulübü seni transfer etmek istiyor.": "El gran club de la ciudad quiere ficharte.",
  "Hocanla kal": "Quédate con tu entrenador",
  "Hocan seni hiç unutmayacak. Sadakat bir gün geri döner.": "Tu entrenador nunca lo olvidará. La lealtad un día se devuelve.",
  "Büyük kulübe geç": "Fichar por el gran club",
  "Daha sert sparring, daha iyi ekipman.": "Sparring más duro, mejor material.",
  "Televizyonda ilk kez bir MMA gecesi izledin. Gözünü alamadın.": "Viste por primera vez una velada de MMA en la tele. No podías apartar la vista.",
  "Güreşe de bak": "Prueba también la lucha",
  "Kulübün güreş köşesine gizlice girmeye başladın.": "Empezaste a colarte en el rincón de lucha del club.",
  "Ayakta vuruşa çalış": "Trabaja el golpeo",
  "Gece yarısına kadar gölge boksu.": "Sombra hasta medianoche.",
  "Antrenmanda bileğin burkuldu. Turnuvaya üç hafta var.": "Te torciste la muñeca entrenando. Faltan tres semanas para el torneo.",
  "Sabırlı oldun; bilek tamamen iyileşti.": "Tuviste paciencia; la muñeca se curó del todo.",
  "Sarıp devam et": "Véndalo y sigue",
  "Acıyla çalışmayı öğrendin.": "Aprendiste a entrenar con dolor.",
  "Mahalledeki arkadaşların akşamları dışarı çağırıyor.": "Tus amigos del barrio te llaman para salir por las noches.",
  "Bir akşam git": "Sal una noche",
  "Güldün, eğlendin; kafan dağıldı.": "Te reíste, te divertiste y despejaste la cabeza.",
  "Erken yat": "Acuéstate temprano",
  "Sabah koşusunda herkesten öndeydin.": "En la carrera matinal ibas delante de todos.",
