  "🥇 {0} şampiyonu oldun!": "🥇 ¡Ganaste el {0}!",
  "🎽 Milli takıma seçildin! Sıradaki durak: Gençler Dünya Şampiyonası.": "🎽 ¡Entraste en la selección! Próxima parada: el Mundial Júnior.",
