  "🌱 {0} yıllık {1} geçmişinden sonra MMA'ya geçiyorsun: {2} altın madalya.": "🌱 Tras {0} años de {1}, das el salto a MMA: {2} medallas de oro.",
  "GENÇLİK YOLU · {0} YAŞ · {1}": "CAMINO JUVENIL · {0} AÑOS · {1}",
  "Her yıl bir karar, her yıl bir turnuva. 18'inde MMA seni bekliyor.": "Cada año una decisión y un torneo. A los 18 te espera el MMA.",
