  "Bir yıl daha {0} ({1} yaş)": "Un año más de {0} ({1} años)",
  "Kafes seni çağırıyor. Erken geçersen gelişecek zamanın çok olur; bir yıl daha kalırsan biraz daha olgun başlarsın.": "La jaula te llama. Si das el salto pronto tendrás más tiempo para crecer; si te quedas un año más empezarás algo más maduro.",
